// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val) internal {
        vm.assume(true);
        try c.SetMinSum(_val) {} catch { return; }
        assertTrue(c.MinSum() != _val + 1);
    }

    function testFuzz_run(uint256 _val) public {
        _val = bound(_val, 0, 1000000000000000000000000000000);
        _run(_val);
    }

    receive() external payable {}
}
